void Solver::bump_var(int var, double coeff) {
    // compute increment
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale when a single activity becomes too large
    const double ACT_LIMIT = 1e150;
    const double SCALE = 1e-100;
    if (activity[var] > ACT_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Also keep var_inc itself bounded to avoid overflow in future increments
    if (var_inc > ACT_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // update VSIDS heap if needed
    if (vsids.inHeap(var)) vsids.update(var);
}
